function restDayProfit(prices: number[]): number {
  const go = (i: number, holding: boolean): number => {
    if (i >= prices.length) return 0;
    const wait = go(i + 1, holding);
    if (holding) return Math.max(wait, prices[i] + go(i + 2, false)); // sell, then rest tomorrow
    return Math.max(wait, go(i + 1, true) - prices[i]);               // buy
  };
  return go(0, false);
}

