function restDayProfit(prices: number[]): number {
  const n = prices.length;
  const HOLD = 0, SOLD = 1, REST = 2;
  const dp: number[][] = Array.from({ length: n }, () => [0, 0, 0]);
  dp[0] = [-prices[0], -Infinity, 0];
  for (let i = 1; i < n; i++) {
    const y = dp[i - 1], p = prices[i];
    dp[i][HOLD] = Math.max(y[HOLD], y[REST] - p); // keep holding, or buy after a free day
    dp[i][SOLD] = y[HOLD] + p;                     // sell what we held
    dp[i][REST] = Math.max(y[REST], y[SOLD]);      // do nothing without a share
  }
  return Math.max(dp[n - 1][SOLD], dp[n - 1][REST]);
}

