class Solution:
    def restDayProfit(self, prices: List[int]) -> int:
        n = len(prices)
        # dp[i] = [hold, sold, rest] at the end of day i
        dp = [[0, 0, 0] for _ in range(n)]
        dp[0] = [-prices[0], -math.inf, 0]
        for i in range(1, n):
            hold, sold, rest = dp[i - 1]
            p = prices[i]
            dp[i] = [max(hold, rest - p), hold + p, max(rest, sold)]
        return max(dp[n - 1][1], dp[n - 1][2])

